from workshop.planner import FollowupPlanner
from workshop.service import complete_job, schedule_followup


class FakeLedger:

    def __init__(self):
        self.posted = []

    def post_parts(self, job_id, parts_used):
        self.posted.append((job_id, parts_used))


class FakeJob:

    def __init__(self, job_id):
        self.id = job_id
        self.state = "open"


def test_complete_job_marks_finished():
    job = FakeJob("JOB-2214")
    assert complete_job(job, 6, FakeLedger()) == "finished"


def test_followup_not_queued_after_completion():
    job = FakeJob("JOB-2215")
    planner = FollowupPlanner()
    complete_job(job, 4, FakeLedger())
    assert schedule_followup(job, planner) is False
    assert planner.pending() == []

