"""Follow-up queue for the machine-shop planner."""


class FollowupPlanner:
    """Tracks the follow-up visits the shop still owes a customer."""

    def __init__(self):
        self.queue = []

    def enqueue_followup(self, job_id):
        self.queue.append(job_id)
        return job_id

    def pending(self):
        return list(self.queue)
